let time = Date.now();

return [
    {
        topic: "Temperature",
        payload: msg.payload.temperature,
        timestamp: time
    },
    {
        topic: "Humidity",
        payload: msg.payload.humidity,
        timestamp: time
    },
    {
        topic: "Light",
        payload: msg.payload.light,
        timestamp: time
    }
];

const now = Date.now();
const TIMEOUT = 30000; // ข้อมูลหายเกิน 30 วินาที ถือว่า Disconnect

const p = msg.payload || {};
let alerts = [];

// ⚙️ เกณฑ์แจ้งเตือนระบบไฟฟ้า 3 เฟส
const VOLT_MIN = 198.0;       // ไฟตก (< 198V)
const VOLT_MAX = 242.0;       // ไฟเกิน (> 242V)
const CURRENT_MAX = 15.0;     // กระแสเกินต่อเฟส (> 15A)
const TOTAL_POWER_MAX = 5000; // กำลังไฟฟ้ารวมเกิน (> 5000W)

// ใช้เวลาไทย (Asia/Bangkok)
const thaiHour = Number(
    new Intl.DateTimeFormat("en-GB", {
        timeZone: "Asia/Bangkok",
        hour: "2-digit",
        hourCycle: "h23"
    }).format(new Date(now))
);

// 🟢 จุดที่ 1: เปลี่ยนเงื่อนไขช่วงเวลาเป็น 18:00 น. ถึง 06:00 น. (thaiHour >= 19 หรือ < 8)
const isNightWindow = thaiHour >= 18 || thaiHour < 6;

// สถานะเริ่มต้นของ Function Node
let startedAt = context.get("startedAt");
if (!startedAt) {
    startedAt = now;
    context.set("startedAt", startedAt);
}

// เช็กว่ามีข้อมูล PZEM 3 เฟส เข้ามาหรือไม่
const hasPzemData =
    typeof p.totalPower === "number" ||
    typeof p.voltage === "number" ||
    [p.l1, p.l2, p.l3].some(phase => phase && typeof phase.voltage === "number");

// ใช้ชื่อ Key ภาษาอังกฤษที่ไม่มีเว้นวรรคหรือวงเล็บ
const devices = {
    DHT11: typeof p.temperature === "number",
    LDR: typeof p.light === "number",
    PZEM_3Phase: hasPzemData
};

// ==========================================
// 1. WATCHDOG CHECK (เรียกจาก Inject Node ด้วย msg.topic = "watchdog")
// ==========================================
if (msg.topic === "watchdog") {
    for (const device of Object.keys(devices)) {
        const lastSeen = context.get("lastSeen_" + device);
        const previous = context.get("disconnected_" + device);

        const referenceTime = lastSeen || startedAt;
        const disconnected = now - referenceTime > TIMEOUT;

        // ชื่อแสดงผลในไลน์/โทรเลข
        const displayName = device === "PZEM_3Phase" ? "PZEM-004T (3-Phase)" : device;

        // แจ้งเตือนครั้งเดียวเมื่อ Disconnect
        if (disconnected && previous !== true) {
            alerts.push(`🔴 ${displayName} Disconnect: ไม่พบข้อมูลเกิน 30 วินาที`);
        }

        // แจ้งเตือนเมื่อกลับมาเชื่อมต่อ
        if (!disconnected && previous === true) {
            alerts.push(`🟢 ${displayName} กลับมาเชื่อมต่อแล้ว`);
        }

        context.set("disconnected_" + device, disconnected);
    }

    if (alerts.length === 0) return null;

    msg.payload = {
        chatId: 8602127088,
        type: "message",
        content: "🚨 แจ้งเตือน IoT Watchdog\n\n" + alerts.join("\n")
    };

    return msg;
}

// ==========================================
// 2. บันทึกเวลาที่ได้รับข้อมูล & อัปเดตการกลับมาเชื่อมต่อ
// ==========================================
for (const device of Object.keys(devices)) {
    if (devices[device]) {
        context.set("lastSeen_" + device, now);

        const displayName = device === "PZEM_3Phase" ? "PZEM-004T (3-Phase)" : device;

        if (context.get("disconnected_" + device) === true) {
            context.set("disconnected_" + device, false);
            alerts.push(`🟢 ${displayName} กลับมาเชื่อมต่อแล้ว`);
        }
    }
}

// ==========================================
// 3. ตรวจสอบความผิดปกติระบบไฟฟ้า 3 เฟส (L1, L2, L3)
// ==========================================
if (hasPzemData) {
    const phases = [
        { name: "L1", data: p.l1 },
        { name: "L2", data: p.l2 },
        { name: "L3", data: p.l3 }
    ];

    // 3.1 ตรวจสอบไฟตก / ไฟเกิน / กระแสเกิน แยกตามเฟส
    phases.forEach(ph => {
        if (!ph.data) return;
        const v = Number(ph.data.voltage || 0);
        const i = Number(ph.data.current || 0);
        const keyPrefix = "pzem_alert_" + ph.name;

        // ไฟตก
        const isVoltLow = v > 0 && v < VOLT_MIN;
        if (isVoltLow && context.get(keyPrefix + "_vlow") !== true) {
            alerts.push(`⚠️ [${ph.name}] ไฟตก: ${v.toFixed(1)} V`);
        }
        context.set(keyPrefix + "_vlow", isVoltLow);

        // ไฟเกิน
        const isVoltHigh = v > VOLT_MAX;
        if (isVoltHigh && context.get(keyPrefix + "_vhigh") !== true) {
            alerts.push(`🚨 [${ph.name}] ไฟเกิน: ${v.toFixed(1)} V`);
        }
        context.set(keyPrefix + "_vhigh", isVoltHigh);

        // กระแสเกิน
        const isCurrentHigh = i > CURRENT_MAX;
        if (isCurrentHigh && context.get(keyPrefix + "_ihigh") !== true) {
            alerts.push(`🔥 [${ph.name}] กระแสเกิน: ${i.toFixed(2)} A`);
        }
        context.set(keyPrefix + "_ihigh", isCurrentHigh);

        // ตรวจสอบกระแสต่ำกว่า 2.00 A
        // แจ้งเตือนเมื่อมีกระแสไหลมากกว่า 0 A แต่น้อยกว่า 2.00 A
        const isCurrentLow = i > 0 && i > 2.00;

        if (
            isCurrentLow &&
            context.get(keyPrefix + "_ilow") !== true
        ) {
            alerts.push(
                `⚡ [${ph.name}] กระแสสูงกว่า 2.00 A: ${i.toFixed(2)} A\nมีคนใช้ไฟอยู่`
            );
        }

        context.set(keyPrefix + "_ilow", isCurrentLow);

    });

    // 3.2 ตรวจสอบไฟขาดเฟส (Phase Loss)
    const activeVolts = phases.map(ph => ph.data ? Number(ph.data.voltage || 0) : 0);
    if (activeVolts.some(v => v > 100)) {
        phases.forEach(ph => {
            const v = ph.data ? Number(ph.data.voltage || 0) : 0;
            const key = "pzem_alert_" + ph.name + "_loss";
            const isLoss = v < 50;

            if (isLoss && context.get(key) !== true) {
                alerts.push(`❌ [${ph.name}] ไฟขาดเฟส! (0 V)`);
            }
            context.set(key, isLoss);
        });
    }

    // 3.3 ตรวจสอบกำลังไฟฟ้ารวมเกิน (Total Power Overload)
    const totalPower = Number(p.totalPower || 0);
    const isPowerOverload = totalPower > TOTAL_POWER_MAX;
    if (isPowerOverload && context.get("pzem_alert_power_overload") !== true) {
        alerts.push(`💥 โหลดไฟฟ้ารวมเกินกำหนด: ${totalPower.toFixed(1)} W`);
    }
    context.set("pzem_alert_power_overload", isPowerOverload);
}

// ==========================================
// 4. ตรวจสอบอุณหภูมิและแสง (เฉพาะช่วง 19:00 น. ถึง 08:00 น.)
// ==========================================
// 🟢 จุดที่ 2: ใช้เงื่อนไข isNightWindow ในการตรวจจับ
// ==========================================
// 4. ตรวจสอบอุณหภูมิและแสง (เฉพาะช่วง 19:00 น. ถึง 08:00 น.)
// ==========================================
if (isNightWindow) {
    // 🟢 ดึงค่าโดยรองรับทั้งชื่อเต็มและชื่อย่อจากเซ็นเซอร์จริง
    const temp = p.temperature ?? p.temp;
    const light = p.light ?? p.lux ?? p.ldr;

    // ⚙️ ตั้งเกณฑ์: อุณหภูมิสูงเกิน 30°C หรือ แสงเกิน 300 lx
    const tempAlert = typeof temp === "number" && temp >= 30; // ปรับเตือนเมื่อร้อน >= 30°C
    const lightAlert = typeof light === "number" && light > 300;

    if (tempAlert && context.get("tempAlert") !== true) {
        alerts.push(`🌡️ อุณหภูมิสูงเกินเกณฑ์: ${temp} °C`);
    }

    if (lightAlert && context.get("lightAlert") !== true) {
        alerts.push(`💡 เปิดไฟทิ้งไว้ (ความสว่าง: ${light} lx)`);
    }

    context.set("tempAlert", tempAlert);
    context.set("lightAlert", lightAlert);
} else {
    // ช่วงกลางวัน รีเซ็ตสถานะ
    context.set("tempAlert", false);
    context.set("lightAlert", false);
}

// ==========================================
// 5. ส่งข้อความออกไปยัง Telegram Bot Node
// ==========================================
if (alerts.length === 0) return null;

msg.payload = {
    chatId: 8602127088,
    type: "message",
    content: "🚨 แจ้งเตือนระบบ IoT\n\n" + alerts.join("\n")
};

return msg;

let d = msg.payload;

msg.topic = `
INSERT INTO sensor_data
(
    temperature,
    humidity,
    light
)
VALUES (?, ?, ?)
`;

msg.payload = [
    d.temperature,
    d.humidity,
    d.light
];

return msg;

const allowed = {
    'dashboard.html': 'dashboard.html',
    'analytics.html': 'analytics.html',
    'energy.html': 'energy.html',
    'history.html': 'history.html',
    'settings.html': 'settings.html',
    'style.css': 'style.css',
    'common.js': 'common.js'
};

let requested = (msg.req.params && msg.req.params.file) ? msg.req.params.file : '';

// Redirect /web or /web/ to /web/dashboard.html for clean relative paths
if (!requested || requested === '') {
    msg.statusCode = 302;
    msg.headers = { 'Location': '/web/dashboard.html' };
    msg.payload = 'Redirecting...';
    return [null, msg];
}

let target = allowed[requested] || 'dashboard.html';
msg.filename = 'c:/Users/ASUS TUF/.node-red/' + target;

if (target.endsWith('.css')) {
    msg.headers = { 'content-type': 'text/css; charset=utf-8' };
} else if (target.endsWith('.js')) {
    msg.headers = { 'content-type': 'application/javascript; charset=utf-8' };
} else {
    msg.headers = { 'content-type': 'text/html; charset=utf-8' };
}

return [msg, null];

// ดึง topic เช่น ku/engineering/power3phase/data/1/volt
var parts = msg.topic.split('/');
var phaseId = parts[4];   // "1", "2", หรือ "3"
var metric  = parts[5];   // "volt", "amp", "watt", "energy_wh", "timestamp"
var val     = msg.payload;

// 🟢 ฟังก์ชันสร้างเวลาปัจจุบันของ Node-RED Server (รูปแบบ YYYY-MM-DD HH:mm:ss)
function getServerTime() {
    var now = new Date();
    var pad = function(n) { return String(n).padStart(2, '0'); };
    return now.getFullYear() + '-' +
           pad(now.getMonth() + 1) + '-' +
           pad(now.getDate()) + ' ' +
           pad(now.getHours()) + ':' +
           pad(now.getMinutes()) + ':' +
           pad(now.getSeconds());
}

// ใช้งาน memory ของ flow เพื่อรวมค่าต่อเฟส
var storeKey = "phase_" + phaseId;
var data = flow.get(storeKey) || {
    phase: parseInt(phaseId),
    timestamp: null,
    volt: null,
    amp: null,
    watt: null,
    energy_wh: null
};

// 🟢 ปรับแก้จุดนี้: หาก metric เป็น "timestamp" ให้เขียนเวลา Server ปัจจุบันทับค่าที่ค้างมาจากบอร์ด
if (metric === "timestamp") data.timestamp = getServerTime();

if (metric === "volt")      data.volt = parseFloat(val);
if (metric === "amp")       data.amp = parseFloat(val);
if (metric === "watt")      data.watt = parseFloat(val);
if (metric === "energy_wh") data.energy_wh = parseFloat(val);

flow.set(storeKey, data);

/* เก็บค่าล่าสุดของแต่ละเฟสไว้ให้ API อ่าน */
flow.set("pzem_latest_phase_" + phaseId, {
    phase: parseInt(phaseId),
    timestamp: data.timestamp,
    volt: data.volt,
    amp: data.amp,
    watt: data.watt,
    energy_wh: data.energy_wh
});

// เมื่อได้รับข้อมูลครบทั้ง 5 พารามิเตอร์ จึงประกอบคำสั่ง SQL
if (data.timestamp && data.volt !== null && data.amp !== null && data.watt !== null && data.energy_wh !== null) {
    var sql = "INSERT INTO pzem_3phase_logs (device_time, phase_id, voltage, current, power, energy) VALUES ('"
              + data.timestamp + "', " 
              + data.phase + ", " 
              + data.volt + ", " 
              + data.amp + ", " 
              + data.watt + ", " 
              + data.energy_wh + ");";

    // รีเซ็ตค่าเพื่อรอรอบถัดไป
    flow.set(storeKey, null);

    return { topic: sql };
}

return null; // ยังไม่ครบทุกค่า ให้รอข้อความถัดไป

let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch(e) {}
}
if (!p || typeof p !== 'object') {
    p = {};
}

let out = {
    // Environmental
    temperature: p.temperature !== undefined ? p.temperature : p.temp,
    humidity: p.humidity !== undefined ? p.humidity : p.humi,
    light: p.light !== undefined ? p.light : p.ldr,

    // PZEM-004T Electrical parameters
    voltage: p.voltage !== undefined ? p.voltage : (p.volt !== undefined ? p.volt : p.v),
    current: p.current !== undefined ? p.current : (p.current_a !== undefined ? p.current_a : (p.amp !== undefined ? p.amp : p.i)),
    power: p.power !== undefined ? p.power : (p.watt !== undefined ? p.watt : (p.power_w !== undefined ? p.power_w : p.p)),
    energy: p.energy !== undefined ? p.energy : (p.kwh !== undefined ? p.kwh : (p.energy_kwh !== undefined ? p.energy_kwh : p.e)),
    frequency: p.frequency !== undefined ? p.frequency : (p.freq !== undefined ? p.freq : (p.hz !== undefined ? p.hz : p.f)),
    pf: p.pf !== undefined ? p.pf : (p.power_factor !== undefined ? p.power_factor : p.powerFactor),

    topic: msg.topic || p.topic,
    timestamp: Date.now()
};

msg.payload = JSON.stringify(out);
return msg;

const rows = msg.payload;

if (!Array.isArray(rows) || rows.length === 0) {
    msg.payload = {
        success: false,
        message: "ไม่พบข้อมูล PZEM ใน Database"
    };
    msg.statusCode = 404;
    return msg;
}

// ฟังก์ชันช่วยค้นหาแถวล่าสุดตาม phase_id (1, 2, 3)
const getPhaseData = (phaseId) => {
    const row = rows.find(r => Number(r.phase_id) === phaseId);

    if (!row) {
        return {
            voltage: 0,
            current: 0,
            power: 0,
            energyWh: 0,
            energyKwh: 0,
            timestamp: null
        };
    }

    return {
        voltage: Number(row.voltage || 0),
        current: Number(row.current || 0),
        power: Number(row.power || 0),
        energyWh: Number(row.energy || 0),
        energyKwh: Number(row.energy || 0) / 1000,
        timestamp: row.recorded_at || row.device_time
    };
};

// ดึงข้อมูลแยกตาม phase_id
const l1 = getPhaseData(1);
const l2 = getPhaseData(2);
const l3 = getPhaseData(3);

const totalPower = l1.power + l2.power + l3.power;
const totalEnergy = l1.energyKwh + l2.energyKwh + l3.energyKwh;

// ดึง timestamp ล่าสุดที่มีอยู่
const latestTimestamp = [l1, l2, l3].map(p => p.timestamp).find(Boolean) || new Date().toLocaleString('th-TH');

msg.payload = {
    success: true,
    phases: { l1, l2, l3 },
    l1,
    l2,
    l3,
    totalPower,
    totalEnergy,
    timestamp: latestTimestamp
};

msg.headers = {
    "Content-Type": "application/json; charset=utf-8"
};

return msg;

// กำหนดคำสั่ง SQL เพื่อดึงข้อมูล 15 แถวล่าสุดมาจัดกลุ่ม 3 เฟส
msg.topic = "SELECT * FROM pzem_3phase_logs ORDER BY id DESC LIMIT 15;";
return msg;

// กำหนดคำสั่ง SQL เพื่อดึงข้อมูล 15 แถวล่าสุดมาจัดกลุ่ม 3 เฟส
msg.topic = "SELECT * FROM sensor_data ORDER BY id DESC LIMIT 1000;"
return msg;

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
};

if (Array.isArray(msg.payload)) {
    msg.payload = msg.payload.map(row => ({
        id: row.id,
        temp: row.temp ?? row.temperature ?? null,
        humi: row.humi ?? row.humidity ?? null,
        light: row.light ?? row.lux ?? row.ldr ?? null,
        recorded_at: row.recorded_at || row.created_at || new Date().toISOString()
    }));
} else {
    msg.payload = [];
}

return msg;
